import java.util.HashMap;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

public class Exercise {
    public static void main(String[] args) {
        Map<String, List<String>> groups = new HashMap<>();
        String[] names = {"Alice", "Bob", "Anna", "Brian", "Charlie"};
        for (String name : names) {
            String key = String.valueOf(name.charAt(0));
            groups.computeIfAbsent(key, k -> new ArrayList<>()).add(name);
        }
        System.out.println("Groups: " + groups);
        // e.g. {A=[Alice, Anna], B=[Bob, Brian], C=[Charlie]}

        Map<String, String> statusMap = new HashMap<>();
        statusMap.put("order1", "shipped");
        statusMap.put("order2", "pending");
        statusMap.putIfAbsent("order3", "new");
        statusMap.putIfAbsent("order1", "overwritten"); // won't change
        statusMap.computeIfPresent("order1", (k, v) -> v + " (verified)");
        statusMap.computeIfPresent("order99", (k, v) -> v + " (verified)"); // no-op
        System.out.println("Status map: " + statusMap);
    }
}

