import java.util.Iterator;
import java.util.Map;

public class Exercise {
    public static void main(String[] args) {
        Map<String, Integer> map1 = new HashMap<>();
        map1.put("apple", 3);
        map1.put("banana", 2);
        Map<String, Integer> map2 = new HashMap<>();
        map2.put("banana", 5);
        map2.put("cherry", 1);

        // Merge map2 into map1, summing counts for duplicate keys
        map2.forEach((k, v) -> map1.merge(k, v, Integer::sum));
        System.out.println("Merged: " + map1); // {apple=3, banana=7, cherry=1}

        map1.forEach((k, v) -> System.out.println(k + " => " + v));

        // Remove entries where count < 4
        Iterator<Map.Entry<String, Integer>> it = map1.entrySet().iterator();
        while (it.hasNext()) {
            Map.Entry<String, Integer> e = it.next();
            if (e.getValue() < 4) {
                it.remove();
            }
        }
        System.out.println("After removal: " + map1); // {banana=7}
    }
}

