import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class Exercise {
    public static void main(String[] args) {
        List<String> mutable = new ArrayList<>(Arrays.asList("a", "b", "c"));
        List<String> unmod = Collections.unmodifiableList(mutable);
        System.out.println("Unmodifiable view: " + unmod); // [a, b, c]

        mutable.add("d"); // modifying original is fine
        System.out.println("After adding to mutable: " + unmod); // [a, b, c, d]

        try {
            unmod.add("e"); // throws!
        } catch (UnsupportedOperationException e) {
            System.out.println("Cannot modify via unmodifiable view: " + e.getClass().getSimpleName());
        }

        List<String> synced = Collections.synchronizedList(new ArrayList<>());
        synced.add("x");
        synced.add("y");
        synchronized (synced) {
            for (String s : synced) {
                System.out.println("Synced element: " + s);
            }
        }
    }
}

