        System.out.println("Frequencies: " + new TreeMap<>(freq));
        // {a=1, g=2, i=1, m=2, n=1, o=1, p=1, r=2}

        freq.replaceAll((k, v) -> v * v);
        System.out.println("Squared: " + new TreeMap<>(freq));
        // {a=1, g=4, i=1, m=4, n=1, o=1, p=1, r=4}
